builder.Services.AddControllers(options =>
{
    options.CacheProfileNames.Add("ShortCache");
});

builder.Services.AddResponseCaching();

builder.Services.Configure<Microsoft.AspNetCore.Mvc.ResponseCacheOptions>(options =>
{
    options.DefaultProfileVaryByHeader = "Accept-Encoding";
});

// Controller
[ApiController]
[Route("api/[controller]")]
public class ProductsController : ControllerBase
{
    [HttpGet]
    [ResponseCache(CacheProfileName = "ShortCache")]
    public IActionResult GetAll() => Ok(_products);

    [HttpGet("{id}")]
    [ResponseCache(Duration = 3600, VaryByQueryKeys = new[] { "id" })]
    public IActionResult Get(int id) => Ok(_repo.Get(id));
}
